package thumbs

import "image"

type Cache struct {
	maxBytes  int64
	usedBytes int64
	entries   map[string]*entry
}

type entry struct {
	img  *image.RGBA
	size int64
}

func NewCache(maxBytes int64) *Cache {
	return &Cache{maxBytes: maxBytes, entries: make(map[string]*entry)}
}

func (c *Cache) Get(key string) (*image.RGBA, bool) {
	e, ok := c.entries[key]
	if !ok {
		return nil, false
	}
	return e.img, true
}

func (c *Cache) Add(key string, img *image.RGBA) {
	size := int64(len(img.Pix))
	c.entries[key] = &entry{img: img, size: size}
	c.usedBytes += size
}

