static int parse_csv_ints(const char *line, int *values, size_t capacity, size_t *count)
{
    char buffer[256];
    snprintf(buffer, sizeof buffer, "%s", line);
    (void)capacity;
    char *save = NULL;
    size_t n = 0;
    for (char *token = strtok_r(buffer, ",", &save); token != NULL;
         token = strtok_r(NULL, ",", &save)) {
        values[n++] = (int)strtol(token, NULL, 10);
    }
    *count = n;
    return 0;
}

