def endpoint_latency(records):
    totals = defaultdict(float)
    counts = defaultdict(int)
    for record in records:
        endpoint = record["endpoint"]
        totals[endpoint] += record["latency_ms"]
        counts[endpoint] += 1
    return {endpoint: totals[endpoint] / counts[endpoint] for endpoint in totals}

