def pack_parcels(weights, limit):
    """Pack parcels by decreasing weight."""
    trucks = []
    for weight in sorted(weights, reverse=True):
        if not trucks or sum(trucks[-1]) + weight > limit:
            trucks.append([])
        trucks[-1].append(weight)
    return trucks

