from collections import defaultdict

def weekly_summary(readings, week_start, low=0.0, high=5.0):
    """Count pressure drops by site from week_start onward."""
    counts = defaultdict(lambda: {"normal": 0, "out_of_range": 0})
    for reading in readings:
        if reading["date"] < week_start:
            continue
        bucket = "normal" if low <= reading["pressure_drop"] <= high else "out_of_range"
        counts[reading["site"]][bucket] += 1
    return dict(counts)

