#include <stdint.h>

typedef struct {
    uint8_t code;
    const char *name;
} Opcode;

static const Opcode opcodes[] = {
    {0x04, "NOP"},
    {0x19, "LDA"},
    {0x37, "XOR"},
    {0x82, "JMP"},
    {0xD2, "HALT"}
};

const char *opcode_name(uint8_t code) {
    size_t low = 0;
    size_t high = sizeof(opcodes) / sizeof(opcodes[0]) - 1;

    while (low < high) {
        size_t mid = low + (high - low) / 2;
        if (opcodes[mid].code < code) {
            low = mid + 1;
        } else if (opcodes[mid].code > code) {
            high = mid;
        } else {
            return opcodes[mid].name;
        }
    }
    return NULL;
}

