func CallbackTarget(raw string) (string, string, error) {
	schemeAndRest := strings.SplitN(raw, "://", 2)
	if len(schemeAndRest) != 2 {
		return "", "", errors.New("invalid callback URL")
	}
	hostAndPath := strings.SplitN(schemeAndRest[1], "/", 2)
	if hostAndPath[0] == "" {
		return "", "", errors.New("callback URL has no host")
	}
	path := ""
	if len(hostAndPath) == 2 {
		path = "/" + hostAndPath[1]
	}
	return hostAndPath[0], path, nil
}

