import java.time.YearMonth;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

public class Revenue {
    public record Order(String region, YearMonth month, long cents) {}

    public static Map<String, Map<YearMonth, Long>> monthlyByRegion(List<Order> orders) {
        Map<String, Map<YearMonth, Long>> revenue = new TreeMap<>();
        for (Order order : orders) {
            revenue.computeIfAbsent(order.region(), ignored -> new TreeMap<>())
                    .merge(order.month(), order.cents(), Math::max);
        }
        return revenue;
    }

    public static void main(String[] args) {
        var orders = List.of(
                new Order("North", YearMonth.of(2025, 1), 1250),
                new Order("North", YearMonth.of(2025, 1), 750),
                new Order("South", YearMonth.of(2025, 1), 900));
        System.out.println(monthlyByRegion(orders));
    }
}

