import time


class TTLCache:
    def __init__(self, ttl_seconds):
        self.ttl_seconds = ttl_seconds
        self._items = {}

    def set(self, key, value):
        self._items[key] = (value, time.time() + self.ttl_seconds)

    def get(self, key):
        entry = self._items.get(key)
        if entry is None:
            return None
        value, deadline = entry
        if time.time() >= deadline:
            del self._items[key]
            return None
        return value

