export type SiteSummary = {
  site: string;
  weekEnding: string;
  normal: number;
  outOfRange: number;
};

export function summarizeWeekly(readings: AcuityReading[]): SiteSummary[] {
  const summaries = new Map<string, SiteSummary>();
  for (const reading of readings) {
    const summary = summaries.get(reading.site) ?? {
      site: reading.site,
      weekEnding: reading.weekEnding,
      normal: 0,
      outOfRange: 0,
    };
    const denominator = Number(reading.visualAcuity.split("/")[1]);
    if (denominator <= 40) summary.normal += 1;
    summaries.set(reading.site, summary);
  }
  return Array.from(summaries.values());
}

