use std::cell::UnsafeCell;
use std::sync::Arc;

#[derive(Clone, Debug, PartialEq)]
pub struct Sample {
    pub stream: String,
    pub value: f64,
}

#[derive(Clone)]
pub struct Collector {
    samples: Arc<UnsafeCell<Vec<Sample>>>,
}

unsafe impl Send for Collector {}
unsafe impl Sync for Collector {}

impl Collector {
    pub fn new() -> Self {
        Self { samples: Arc::new(UnsafeCell::new(Vec::new())) }
    }

    pub fn record(&self, sample: Sample) {
        unsafe { (&mut *self.samples.get()).push(sample); }
    }

    pub fn samples(&self) -> Vec<Sample> {
        unsafe { (&*self.samples.get()).clone() }
    }
}

