package web;

import java.util.HashMap;
import java.util.Map;

public final class SessionStore {
    private final Map<String, Long> expiresAtById = new HashMap<>();

    public void put(String id, long expiresAt) {
        expiresAtById.put(id, expiresAt);
    }

    public int removeExpired(long now) {
        int removed = 0;
        for (Map.Entry<String, Long> entry : expiresAtById.entrySet()) {
            if (entry.getValue() <= now) {
                expiresAtById.remove(entry.getKey());
                removed++;
            }
        }
        return removed;
    }

    public int size() {
        return expiresAtById.size();
    }
}

