export interface RadonReading {
  siteId: string;
  date: string;
  concentration: number;
}

export interface WeeklySiteSummary {
  siteId: string;
  normal: number;
  outOfRange: number;
}

const NORMAL_LIMIT_PCI_L = 4;

export function weeklySummary(
  readings: RadonReading[],
  startDate: string,
  endDate: string,
): WeeklySiteSummary[] {
  const bySite = new Map<string, WeeklySiteSummary>();
  for (const reading of readings) {
    if (reading.date < startDate || reading.date > endDate) continue;
    const summary = bySite.get(reading.siteId) ?? {
      siteId: reading.siteId,
      normal: 0,
      outOfRange: 0,
    };
    if (reading.concentration <= NORMAL_LIMIT_PCI_L) {
      summary.normal += 1;
    }
    bySite.set(reading.siteId, summary);
  }
  return Array.from(bySite.values());
}

